# ── T-12571 (SPEC-0205 rules 5/6, SPEC-0036) — the prototype readings of a card's `prototype_ref` ──
# audit-pre: the prototype diff is the ТЗ, plus the overlay below. audit-post: the `prototype_identity`
# line PROJECTS the L2a `spike_content_previewed` row (or, after land, the `_checked` row) and CITES it by
# ts — never recomputed. A card WITHOUT `prototype_ref` whose preview reports an IDENTITY hit (rule 2's T1
# whole-file / T3 hunk-subset) is refused before any auditor call; a partial share is rendered as context
# (rule 6 — no refusal arm, no threshold; T-13154); a zero-share card is never asked to declare.
PROTOTYPE_PRE_OVERLAY = (
    "PROTOTYPE (SPEC-0205 rule 5): the prototype diff above is the SPECIFICATION, not the deliverable. A "
    "plan that reduces to copying named paths from it is RED; state your own design, your own tests, and "
    "which prototype findings the plan deliberately does NOT carry.\n"
)


def prototype_diff_text(repo_root, ref: str) -> "str | None":
    """`git diff <merge-base main ref>..<ref>` for the card's prototype tag; None when unresolvable."""
    import subprocess   # noqa: PLC0415
    def _g(*a):
        from lib import git_env as _git_env  # T-13587 — the git child env policy (SPEC-0188 rule 7)
        r = subprocess.run(["git", "-C", str(repo_root), *a], capture_output=True, text=True, errors="replace",
                           env=_git_env._git_child_env())
        return r.stdout if r.returncode == 0 else None
    mb = (_g("merge-base", "main", f"refs/tags/{ref}") or "").strip()
    return _g("diff", f"{mb}..refs/tags/{ref}") if mb else None


def _share_numerator(payload: dict) -> int:
    try:
        return int(str(payload.get("share") or "0").split("/")[0])
    except ValueError:
        return 0


def prototype_identity_projection(row: dict) -> dict:
    """The `prototype_identity` fields, projected from ONE spike_content_previewed/_checked row."""
    d = row.get("data") if isinstance(row.get("data"), dict) else {}
    return {"whole_file_hits": sorted({h.get("file") for h in (d.get("t1_hits") or []) if isinstance(h, dict)}),
            "whole_file_spikes": list(d.get("t1_spikes") or []),
            "hunk_subset": d.get("t3_verdict"), "spikes_matched": list(d.get("spikes_matched") or []),
            "verbatim_share": d.get("share"), "best_spike": d.get("best_spike"), "error": d.get("error"),
            "source_row": f"events.jsonl#ts={row.get('ts')}", "source_type": row.get("type")}


def _identity_hit(payload: dict) -> bool:
    """Rule 2's identity, as the preview reports it: verdict identity, a T1 whole-file hit, or T3 identity."""
    return (payload.get("verdict") == "identity" or bool(payload.get("t1_hits"))
            or payload.get("t3_verdict") == "identity")


def prototype_overlap_refusal(task: dict, payload: dict) -> "str | None":
    """Refusal text when a card WITHOUT prototype_ref carries an IDENTITY hit; else None. A partial share
    (verdict report) is context, never a refusal (SPEC-0205 rule 6, T-13154)."""
    if task.get("prototype_ref") or payload.get("error") or not _identity_hit(payload):
        return None
    spike = payload.get("best_spike") or next(iter(payload.get("spikes_matched") or payload.get("t1_spikes") or []), None) or "spike/<slug>"
    tid = task.get("id")
    return (f"audit post: {tid} carries no `prototype_ref`, but the spike-content preview reports an identity "
            f"hit (verbatim share {payload.get('share')}) against {spike} (SPEC-0205 rule 5/6). A card built on a "
            f"prototype names it: run `bin/yitc-v2 task update {tid} --prototype-ref {spike}` (an annotated "
            f"spike/* tag), then re-run `audit post`. No auditor was invoked; nothing was recorded as a pass.")


def prototype_post_context(repo_root, tid: str, task: dict, sha: str, *, reaudit_after_close: bool,
                           events_path, main_events_path, append_event, utc_now_iso,
                           iter_events, _preview=None) -> "tuple[dict | None, str | None]":
    """(identity projection | None, refusal | None) for a TASK audit-post. One preview fold per call
    (the L2a helper, its row written to `events_path` and cited by ts); a re-audit after close cites the
    land's `spike_content_checked` row and runs no fold."""
    from lib import spike_identity as si   # noqa: PLC0415
    if reaudit_after_close:
        row = None
        for r in iter_events(events_path):   # the ONE injected journal reader (no new consumer)
            if isinstance(r, dict) and r.get("type") == si.CHECKED_EVENT and r.get("task_id") == tid:
                row = r
        return ((prototype_identity_projection(row) if row and task.get("prototype_ref") else None), None)
    stamp = {}

    def _append(etype, task_id, data, events_path=None):   # noqa: ARG001 — the row lands in THIS checkout
        stamp["ts"] = utc_now_iso()
        stamp["row"] = {"ts": stamp["ts"], "type": etype, "task_id": task_id, "data": data}
        return append_event(etype, task_id, data, ts=stamp["ts"])
    payload = (_preview or si.preview_spike_content)(repo_root, sha, events_path=main_events_path,
                                                     append_event=_append, task_id=tid,
                                                     # stderr: stdout is the packet on `--preview`
                                                     _print=lambda s: print(s, file=sys.stderr))
    refusal = prototype_overlap_refusal(task, payload)
    if refusal or "row" not in stamp:
        return None, refusal
    if not task.get("prototype_ref") and (payload.get("error") or _share_numerator(payload) <= 0):
        return None, None   # a bare zero-share card stays inert; a partial share renders as context
    return prototype_identity_projection(stamp["row"]), None


def _merge_tie_ordering_note(churn_tie: dict) -> str:
    """T-12718 — the CHURN-ONLY MERGE TIE ordering note appended to the `### Stage-6 test evidence`
    section of an in-land `--reaudit-after-close` packet whose subject M drifted from the prior audited
    head H ONLY by already-landed main history (T-9543 `_concurrent_merge_churn_only` — the ONE churn
    classifier, SPEC-0165). It states exactly what is attested and what is not: the recorded row is
    NOT relabelled as covering M; the sha gap is the ORDERING of a land (M's own suite run is land's
    mandatory candidate verify, downstream of this audit), not missing proof. Owner directive
    events.jsonl#ts=2026-09-17T14:55:29Z (option (a), the narrow variant)."""
    h = str(churn_tie.get("prior_commit") or "")
