def record_is_absorbable_on_decisions(record) -> bool:
    """T-12376 — the SAVED-RECORD reading of `on_decisions_row_absorbable`, for the ONE reader that
    holds a verdict YAML and not a row: `task commit --absorb`'s superseded-verdict gate. The YAML is
    a PROJECTION of the row; the record seam writes `basis` / `absorbable` / `new_findings` onto it
    from the same computed values. Same conjunction, same fail-closed shape. Pure; never raises."""
    if not isinstance(record, dict):
        return False
    if str(record.get("basis") or "") != ON_DECISIONS_BASIS:
        return False
    if str(record.get("verdict") or "").strip().upper() != "YELLOW":
        return False
    if record.get("absorbable") is not True:
        return False
    entries = record.get("new_findings")
    return (isinstance(entries, list) and bool(entries)
            and all(isinstance(e, dict) and e.get("absorbable") is True for e in entries))


