def _elision_marker(label: str, kept_lines: int, total_lines: int, kept_bytes: int, total_bytes: int) -> str:
    return (f"... [elided: {label} — kept {kept_lines} of {total_lines} lines, "
            f"{kept_bytes} of {total_bytes} bytes; the path IS present in this commit]")


def _render_elision_manifest(elisions, *, floor_clamped: bool) -> list:
    """The manifest — the half of the fix that stops 'not shown' being read as 'not present'."""
    if not elisions:
        return []
    out = [f"{_ELISION_MANIFEST_HEADER} ({len(elisions)} segment(s) shown only in part) ==="]
    out.append("NOTE: every path listed here IS PRESENT in this commit range — only its CONTENT was")
    out.append("bounded to keep the packet readable. \"not shown\" NEVER means \"not present\": do NOT")
    out.append("report a listed path as absent, missing, or uncommitted.")
    if floor_clamped:
        out.append("NOTE: this commit's file headers plus this manifest alone fill the packet budget,")
        out.append("so NO file content is shown at all — the paths below are listed in full regardless.")
    for e in elisions:
        out.append(f"- {e['path']} — kept {e['kept_lines']} of {e['total_lines']} lines, "
                   f"{e['kept_bytes']} of {e['total_bytes']} bytes")
    return out


def _linebytes(line: str) -> int:
    """The emitted cost of one line: its UTF-8 BYTES plus the joining newline.

    BYTES, not characters: a multi-byte-heavy body would otherwise blow a byte ceiling while the
    caller believed it was bounded (T-11136 audit-post pass-1 high finding)."""
    return len(line.encode("utf-8", "replace")) + 1


def _keep_within_budget(body: list, max_lines: int, max_bytes: int) -> tuple[list, int, bool]:
    """Keep the longest prefix of `body` that fits BOTH a line and a BYTE allowance.

    THE single budget-accounting primitive (T-11136 packet bound + T-11140 referenced-file excerpt).
    Extracted, not duplicated: a line-only bound cannot be satisfied by ANY shape of the data —
    90k short lines exhaust a line budget while 80 30KB-lines satisfy it and blow the prompt anyway
    — so every site that inlines content into an audit prompt bounds on both axes THROUGH HERE.
    A second, parallel bounding mechanism is exactly the accretion this refuses.

    Returns (kept_lines, kept_bytes, cut). `cut` is True iff anything was dropped — the caller owns
    what it emits in that case, and MUST name the segment it truncated (the anti-false-absent rule:
    an unnamed omission is indistinguishable from content that was never there).
    """
    kept, kept_b = [], 0
    for ln in body:
        cost = _linebytes(ln)
        if len(kept) + 1 > max_lines or kept_b + cost > max_bytes:
            room = max_bytes - kept_b
            # a SINGLE line may exceed the whole allowance (the 240KB-line shape) — cut WITHIN
            # the line rather than emitting nothing, so the segment still shows real content
            if not kept and room > 1:
                # slice BYTES, then decode with errors="ignore" so a split multi-byte character
                # is DROPPED rather than becoming a 3-byte U+FFFD that re-inflates past `room`
                piece = ln.encode("utf-8", "replace")[:room - 1].decode("utf-8", "ignore")
                kept.append(piece)
                kept_b += _linebytes(piece)
            return kept, kept_b, True
        kept.append(ln)
        kept_b += cost
    return kept, kept_b, False


# ── T-11328: the TOTAL packet bound ────────────────────────────────────────────────────────────────
# The three ceilings above each bound ONE segment. Nothing bounded the join — see AUDIT_MAX_PACKET_BYTES.

_PACKET_MANIFEST_HEADER = "=== packet bound manifest"

# PROTECTED sections — never trimmed, because each carries either the auditor's INSTRUCTIONS or the
