def cmd_audit_run(args: argparse.Namespace, *, _capacity_retry_hint=None, ASPECTS, AUDIT_PROVIDERS, EVENTS_PATH, _append_event, _as_list, _cli_invoked_resource_summary, _die, _find_error_yaml, _parse_audit_verdict, _read_yaml, _reopen_resolved_error, _resolve_audit_model, _resolve_audit_reserve=None, _resolve_audit_provider, _resolve_session_ref, _utc_now_iso, write_text_atomic) -> None:
    """Run one aspect-audit: print its checklist, record --finding(s) as deviation_captured
    events into the errors channel, optionally get an external opinion (--external)."""
    aspect = args.aspect
    if aspect not in ASPECTS:
        _die(f"--aspect must be one of {list(ASPECTS)}")
    # F2 (audit-post): validate --error up-front (before any codex call) — a supplied --error that
    # can't be resolved is a hard error, never a silent skip of the durable ref-back.
    if args.error and _find_error_yaml(args.error) is None:
        _die(f"--error {args.error}: case file not found (0 or >1 match)")
    if aspect == "meta":
        print("NOTE: `meta` is TRIGGER-ONLY (governance change / repeated divergence / owner request) "
              "— not for an ordinary session (patterns/error-friction-tracking.md §Anti-pattern).")
    print(f"aspect-audit: {aspect}  (checklist — see patterns/error-friction-tracking.md §Solution)")
    for q in ASPECTS[aspect]:
        print(f"  - {q}")
    if aspect == "resource":
        # P8 CONSUMER of T-0113's cli_invoked emitter (T-0136): aggregate this session's query cost
        # so the resource checklist is backed by DATA, not just AI introspection. Always prints
        # (zeroed when no rows) so the consumer path is exercised even at zero queries.
        sess = _resolve_session_ref()
        s = _cli_invoked_resource_summary(EVENTS_PATH, sess)
        print(f"cli_invoked summary (session {sess or '<unresolved>'}): {s['n']} "
              f"quer{'y' if s['n'] == 1 else 'ies'}, {s['total_bytes']} stdout bytes / "
              f"{s['total_lines']} lines; {s['dup_groups']} duplicate-fingerprint group(s), "
              f"{s['dup_redundant']} redundant call(s)")
        for verb, fp, c in s["dups"][:5]:
            print(f"  - duplicate: {verb} [{fp}] x{c}")
    findings = _as_list("finding", args.finding or [])
    # kind is OPTIONAL at capture (per D-0086 §2 — decided in triage, not forced here): the old
    # hardcoded kind:"friction" biased every capture toward "friction" (0/14 ever used kind:defect).
    kind = getattr(args, "kind", None)
    for text in findings:
        data = {"relates_to": aspect, "impact": args.impact or "low",
                "finding": text, "captured_via": "audit-run"}  # NB: _append_event owns data.source
        if kind:
            data["kind"] = kind
        if args.fingerprint:
            data["fingerprint"] = args.fingerprint
        _append_event("deviation_captured", args.error or None, data)
    if findings:
        print(f"recorded {len(findings)} deviation_captured event(s) into the errors channel "
              f"(relates_to={aspect}).")
        # Capture-time reopen (D-0086 §2): an incoming fingerprint already in a resolved/waived
        # E-XXXX flips it back to reopened. Wired at the capture SITE (not _append_event) so only a
        # real capture reopens (audit-pre T-0150 F1). Defensive — never breaks the capture above.
        if args.fingerprint:
            _reopen_resolved_error(args.fingerprint)
    if args.external:
        provider = _resolve_audit_provider(False)   # T-12350: provider first (admission)
        model = resolve_model_for_provider(_resolve_audit_model, False, provider)
        probes = "\n".join(f"- {q}" for q in ASPECTS[aspect])
        flist = "\n".join(f"- {t}" for t in findings) or "(none passed — judge the aspect from context)"
        prompt = (f"# Aspect-audit external opinion — {aspect}\n\n"
                  f"## V2 evaluation lens\nEvaluate against CHARTER principles (anti-complexity / "
                  f"done=adopted / documentation-first / single-SoT / AI-independence / Build+Review-only).\n\n"
                  f"## Aspect probes\n{probes}\n\n## Findings to confirm or reject\n{flist}\n\n"
                  f"Confirm or reject each finding (real? promotion-worthy?). Verdict: GREEN / YELLOW / RED.")
        print(f"# Invoking external auditor: {provider}/{model} (aspect={aspect})...", file=sys.stderr)
        _aspect_t0 = time.monotonic()   # T-12007 — this path sends no audit_prompt_sent, so the
        # invocation start IS its anchor (the `_audit_duration_ms` fallback contract).
        rc, stdout, stderr = AUDIT_PROVIDERS[provider](prompt, model)
        if rc != 0:
            _die(f"external auditor failed: "   # T-12582
                 f"{auditor_failure_cause(rc, stderr, capacity_hint=_capacity_hint_via(_capacity_retry_hint, model, provider))}")   # T-12603
        print(stdout.rstrip())
        # F1 (audit-post): persist a STRUCTURED verdict (reuse the canonical parser), not just an
        # excerpt, so graph/query consumers can use the external result as a durable promotion basis.
        verdict, _f, _notes = _parse_audit_verdict(stdout)
        _append_event("external_audit_completed", args.error or None,
                      {"stage": f"aspect:{aspect}", "verdict": verdict,
                       "duration_ms": _audit_duration_ms(_aspect_t0),   # T-12007 — REQUIRED (SPEC-0025)
                       "verdict_excerpt": stdout.strip()[-500:], "findings_count": len(findings)})
        # F2: ref the durable verdict back into the E-file (promotion from: basis). --error existence
        # was validated up-front, so a missing/unreadable file here is a hard error (no silent skip).
        if args.error:
            import yaml
            epath = _find_error_yaml(args.error)
            rec = _read_yaml(epath) if epath else {}
            if not rec.get("id"):
                _die(f"--error {args.error}: case file became unreadable — cannot ref-back verdict")
            rec["refs"] = (rec.get("refs") or []) + [
                f"external-aspect-audit:{aspect}:{verdict}:events.jsonl#ts={_utc_now_iso()}"]
            write_text_atomic(epath, state.dump(rec))
            print(f"appended external verdict ({verdict}) ref to {args.error}.", file=sys.stderr)




# ── T-13110: paired re-audit sample (report-only) ─────────────────────────────────────────────────
# The observation rollup compares auditor models across DIFFERENT packets; this re-runs a sample of
# already-judged packets under a candidate model so verdicts are compared on IDENTICAL input. It is a
# finding for the auditor-config owner (SPEC-0202 rule 6) — never a gate, never a verdict rewrite.

AUDIT_PACKET_RETENTION_DAYS = 30


def audit_packet_store_dir(repo_root) -> Path:
    """Machine-local packet store: under the git COMMON dir (outside any worktree, never committed);
    falls back to <repo_root>/.yitc/audit-packets when git is unavailable."""
    from lib import git_env as _git_env  # T-13587 — the git child env policy (SPEC-0188 rule 7)
    try:
        r = subprocess.run(["git", "-C", str(repo_root), "rev-parse", "--path-format=absolute",
                            "--git-common-dir"], capture_output=True, text=True, timeout=10,
                           env=_git_env._git_child_env())
        if r.returncode == 0 and r.stdout.strip():
            return Path(r.stdout.strip()) / "yitc-audit-packets"
    except (OSError, subprocess.SubprocessError):
        pass
    return Path(repo_root) / ".yitc" / "audit-packets"


def _has_default_acl(path) -> bool:
    """True when `path` carries a POSIX default ACL (T-13155). Any failure reads as "no ACL"."""
    try:
        return bool(os.getxattr(str(path), "system.posix_acl_default"))
    except (OSError, AttributeError):
        return False


def shared_store_modes(d: Path, repo_root) -> tuple:
    """(dir_mode, file_mode, acl) for a machine-local store `d` under the git dir — the checkout's
    sharing, not a constant. The ONE derivation for every such store: the audit packet store and the
    session hand-off store (T-13347).

    A chmod over a POSIX ACL rewrites the ACL MASK from the group bits, so the old forced 0700/0600
    zeroed every named entry (mask ---) on a shared checkout (T-13155, X-1704). Under a default ACL
    the store is created 0777/0666 and never chmod-ed — the inherited ACL governs. Otherwise the
    sharing git DECLARES is read by the graph-cache helper (T-11660); none declared = today's
    private 0700/0600."""
    if _has_default_acl(d.parent) or _has_default_acl(d):
        return 0o777, 0o666, True
    file_mode = None
    try:
        from lib import graph as graph_mod

        def _run_git(args, root):
            from lib import git_env as _git_env  # T-13587 — the git child env policy (SPEC-0188 rule 7)
            return subprocess.run(["git", "-C", str(root), *args], capture_output=True, text=True,
                                  timeout=10, env=_git_env._git_child_env())
        file_mode = graph_mod._shared_git_dir_file_mode(d.parent, repo_root=repo_root,
                                                        run_git=_run_git)
    except (OSError, subprocess.SubprocessError, ImportError):
        file_mode = None
    file_mode = file_mode or 0o600
    return file_mode | ((file_mode & 0o444) >> 2), file_mode, False


def persist_audit_packet(prompt: str, repo_root, *, store_dir=None) -> str:
    """Write the packet as <sha256>.txt with the checkout's sharing modes (`shared_store_modes`)
    and prune packets older than the retention window. Never fails an audit, but a write that fails
    is LOUD (a stderr warning), never a silently lost packet (T-13155). Returns the sha256 regardless."""
    import stat as _stat
    data = prompt.encode("utf-8", "replace")
    sha = hashlib.sha256(data).hexdigest()
    d = Path(store_dir) if store_dir else audit_packet_store_dir(repo_root)
    try:
        dir_mode, file_mode, acl = shared_store_modes(d, repo_root)
        d.mkdir(mode=dir_mode, parents=True, exist_ok=True)
        if not acl:
            st = os.stat(d)
            if st.st_uid == os.geteuid():
                os.chmod(d, dir_mode | (st.st_mode & _stat.S_ISGID))
        # Always (re)write via a temp + atomic replace: an existing target of any mode is replaced
        # by a file of the derived mode, and a failed write never leaves a temp behind.
        tmp = d / f".{sha}.{os.getpid()}.tmp"
        try:
            fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, file_mode)
            try:
                if not acl:
                    os.fchmod(fd, file_mode)
                os.write(fd, data)
            finally:
                os.close(fd)
            os.replace(tmp, d / f"{sha}.txt")
        finally:
            try:
                tmp.unlink()
            except OSError:
                pass
    except OSError as e:
        print(f"yitc-v2: WARNING: audit packet {sha[:12]} not persisted to {d}: {e}", file=sys.stderr)
        return sha
    cutoff = time.time() - AUDIT_PACKET_RETENTION_DAYS * 86400
    try:
        for f in list(d.glob("*.txt")) + list(d.glob(".*.tmp")):
            try:
                if f.stat().st_mtime < cutoff:
                    f.unlink()
            except OSError:
                pass
    except OSError:
        pass
    return sha


def load_audit_packet(sha: str, store_dir) -> "bytes | None":
    try:
        return (Path(store_dir) / f"{sha}.txt").read_bytes()
    except (OSError, TypeError):
        return None


def collect_paired_candidates(rows) -> tuple:
    """(records, unpaired). Pairs an `audit_prompt_sent` carrying packet_sha256 to the verdict of the
    SAME attempt key (task_id, stage, session_ref), in ts order. A different-sha prompt arriving while
    one is open makes the earlier AMBIGUOUS (reported unpaired, never given the later verdict); a
    same-sha re-send keeps the attempt open. A completion with no open prompt is ignored."""
    open_by_key: dict = {}
    records, unpaired = [], []
    for r in sorted((r for r in rows if isinstance(r, dict)), key=lambda r: str(r.get("ts") or "")):
        et = r.get("event_type") or r.get("type")
        d = r.get("data") or {}
        tid = r.get("task_id")
        if et == "audit_prompt_sent":
            sha = d.get("packet_sha256")
            if not sha:
                continue
            key = (tid, d.get("stage"), r.get("session_ref"))
            prev = open_by_key.get(key)
            if prev is not None and prev["packet_sha256"] != sha:
                unpaired.append({**prev, "reason": "superseded by a different packet before any verdict"})
            if prev is None or prev["packet_sha256"] != sha:
                open_by_key[key] = {"task_id": tid, "stage": d.get("stage"),
                                    "session_ref": r.get("session_ref"), "packet_sha256": sha}
        elif et in ("audit_pre_completed", "audit_post_completed"):
            stage = "pre" if et == "audit_pre_completed" else "post"
            prev = open_by_key.pop((tid, stage, r.get("session_ref")), None)
            if prev is not None:
                records.append({"task_id": tid, "stage": stage, "packet_sha256": prev["packet_sha256"],
                                "recorded_verdict": d.get("verdict")})
    for prev in open_by_key.values():
        unpaired.append({**prev, "reason": "no recorded verdict for this attempt"})
    return records, unpaired


def paired_audit_sample(records, *, load_packet, invoke_candidate, parse_verdict, floor: int = 5,
                        unpaired=None) -> dict:
    """Re-run each recoverable packet under the candidate and compare verdicts. `load_packet(sha)` ->
    bytes|None; `invoke_candidate(packet_text)` -> stdout; `parse_verdict(stdout)` -> verdict. A packet
    is compared only when loaded AND its bytes hash to the recorded sha; every other one is NAMED in
    `unrecoverable`, never skipped silently. Writes nothing."""
    pairs, unrecoverable, by_verdict = [], [], {}
    for rec in records:
        sha = rec.get("packet_sha256")
        data = load_packet(sha) if sha else None
        if data is None or hashlib.sha256(data).hexdigest() != sha:
            unrecoverable.append({"task_id": rec.get("task_id"), "stage": rec.get("stage"),
                                  "packet_sha256": sha,
                                  "reason": "packet not in store" if data is None
                                  else "stored bytes do not match hash"})
            continue
        sent = data.decode("utf-8")
        cand_sha = hashlib.sha256(sent.encode("utf-8")).hexdigest()
        cand = parse_verdict(invoke_candidate(sent))
        rv = rec.get("recorded_verdict")
        agree = cand == rv
        pairs.append({"task_id": rec.get("task_id"), "stage": rec.get("stage"), "recorded_verdict": rv,
                      "candidate_verdict": cand, "recorded_packet_sha256": sha,
                      "candidate_packet_sha256": cand_sha, "agree": agree})
        b = by_verdict.setdefault(str(rv), {"n": 0, "agree": 0})
        b["n"] += 1
        b["agree"] += int(agree)
    return {"pairs": pairs, "compared": len(pairs), "unrecoverable": unrecoverable,
            "unpaired": list(unpaired or []), "agreement_by_recorded_verdict": by_verdict,
            "below_floor": len(pairs) < floor}
